PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?label WHERE {
  ?z a brick:Zone . ?z rdfs:label ?label .
}  LIMIT 200

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?point ?class ?label ?tsid WHERE {
  ?z rdfs:label ?label .
  ?z brick:hasPoint ?point .
  ?point a ?class .
  OPTIONAL { ?point ref:hasExternalReference ?ext . ?ext ref:hasTimeseriesId ?tsid }
} LIMIT 400

PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
